-- Starting submodules: one per Skill Jar course under each domain, with its course link.
-- Generated by scripts/generate-submodule-seed-sql.ts. Safe to re-run; deletes nothing.
-- After this, edit them in Admin > Domains > (domain) > Submodules.

with seed(track, domain, title, url, ord) as (values
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$Claude Platform & Model Foundations$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-associate-foundations/claude-platform-model-foundations$q$, 1),
  ($q$associate$q$, $q$Prompting and Task Execution$q$, $q$Prompting & Task Execution$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-associate-foundations/prompting-task-execution$q$, 1),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$Evaluating & Validating Claude's Output$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-associate-foundations/evaluating-validating-claudes-output$q$, 1),
  ($q$associate$q$, $q$Workflow Integration and Solution Design$q$, $q$Workflow Integration & Solution Design$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-associate-foundations/workflow-integration-solution-design$q$, 1),
  ($q$associate$q$, $q$Configuration and Knowledge Management$q$, $q$Configuration & Knowledge Management$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-associate-foundations/configuration-knowledge-management$q$, 1),
  ($q$associate$q$, $q$Governance, Risk, and Responsible Use$q$, $q$Governance, Risk & Responsible Use$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-associate-foundations/governance-risk-responsible-use$q$, 1),
  ($q$associate$q$, $q$Troubleshooting and Optimization$q$, $q$Troubleshooting & Optimization$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-associate-foundations/troubleshooting-optimization$q$, 1),
  ($q$developer$q$, $q$Model Selection and Optimization$q$, $q$MSO Foundations$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/mso-foundations$q$, 1),
  ($q$developer$q$, $q$Prompt and Context Engineering$q$, $q$Production-Grade Prompting, Agents & Tool Use$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/production-grade-prompting-agents-tool-use$q$, 1),
  ($q$developer$q$, $q$Agents and Workflows$q$, $q$Production-Grade Prompting, Agents & Tool Use$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/production-grade-prompting-agents-tool-use$q$, 1),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$Production-Grade Prompting, Agents & Tool Use$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/production-grade-prompting-agents-tool-use$q$, 1),
  ($q$developer$q$, $q$Tools and MCPs$q$, $q$Claude Code, MCP & Integration$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/claude-code-mcp-integration$q$, 2),
  ($q$developer$q$, $q$Claude Code$q$, $q$Claude Code, MCP & Integration$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/claude-code-mcp-integration$q$, 1),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$Production-Grade Prompting, Agents & Tool Use$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/production-grade-prompting-agents-tool-use$q$, 1),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$Accelerators & IP Contribution$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/accelerators-ip-contribution$q$, 2),
  ($q$developer$q$, $q$Security and Safety$q$, $q$Production Engineering, Evals & Security$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/production-engineering-evals-security$q$, 1),
  ($q$developer$q$, $q$Eval, Testing, and Debugging$q$, $q$Production Engineering, Evals & Security$q$, $q$https://anthropic-partners.skilljar.com/path/claude-certified-developer-foundations/production-engineering-evals-security$q$, 1)
),
ins as (
  insert into quiz_submodules (module_id, title, order_index)
  select m.id, s.title, s.ord
  from seed s join quiz_modules m on m.title = s.domain and m.track = s.track
  on conflict (module_id, title) do nothing
  returning id
)
select count(*) as submodules_added from ins;

