insert into quiz_skilljar_topics (submodule_id, course_title, lesson_title, url, order_index)
select sm.id, s.title, null, s.url, 1
from seed s
join quiz_modules m on m.title = s.domain and m.track = s.track
join quiz_submodules sm on sm.module_id = m.id and sm.title = s.title
where not exists (select 1 from quiz_skilljar_topics t where t.submodule_id = sm.id and t.url = s.url);

-- Check: expect 17 submodules, one topic each
select m.track, m.title as domain, sm.title as submodule, count(t.id) as topics
from quiz_submodules sm
join quiz_modules m on m.id = sm.module_id
left join quiz_skilljar_topics t on t.submodule_id = sm.id
group by m.track, m.title, sm.title, sm.order_index
order by m.track, m.title, sm.order_index;
